param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('Utf8CloneOracle'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('CloneOracle');$builder=$module.DefineType('Utf8CloneSubclass',[Reflection.TypeAttributes]::Public,[Text.UTF8Encoding]);[void]$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$field=$builder.DefineField('Marker',[int],[Reflection.FieldAttributes]::Public);$derived=$builder.CreateType()
function Conversion([Text.Encoding]$encoding,[bool]$encode){try{if($encode){$value=$encoding.GetBytes([string]::new([char[]]@(65,0xd800,66)))}else{$value=$encoding.GetChars([byte[]]@(65,255,66))};return [ordered]@{ok=$true;units=[int[]]$value}}catch{$e=$_.Exception;while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;index=$e.Index;hResult=$e.HResult}}}
$rows=@()
foreach($profile in 0..5){$source=switch($profile){0{[Text.UTF8Encoding]::new()}1{[Text.UTF8Encoding]::new($true)}2{[Text.UTF8Encoding]::new($false,$true)}3{[Text.UTF8Encoding]::new($true,$true)}4{[Text.Encoding]::UTF8}5{$instance=[Activator]::CreateInstance($derived);$derived.GetField('Marker').SetValue($instance,42);$instance}}
 $clone=[Text.Encoding]$source.Clone();$clone2=[Text.Encoding]([ICloneable]$clone).Clone()
 $rows+=[ordered]@{profile=$profile;sourceType=$source.GetType().FullName;cloneType=$clone.GetType().FullName;clone2Type=$clone2.GetType().FullName;sourceReadOnly=$source.IsReadOnly;cloneReadOnly=$clone.IsReadOnly;clone2ReadOnly=$clone2.IsReadOnly;distinct=[bool](-not [object]::ReferenceEquals($source,$clone));distinctClone2=[bool](-not [object]::ReferenceEquals($clone,$clone2));codePage=$clone.CodePage;preamble=[int[]]$clone.GetPreamble();encoderFallbackSame=[object]::ReferenceEquals($source.EncoderFallback,$clone.EncoderFallback);decoderFallbackSame=[object]::ReferenceEquals($source.DecoderFallback,$clone.DecoderFallback);isCloneable=($clone -is [ICloneable]);marker=$(if($profile -eq 5){$derived.GetField('Marker').GetValue($clone)}else{$null});sourceEncode=(Conversion $source $true);cloneEncode=(Conversion $clone $true);sourceDecode=(Conversion $source $false);cloneDecode=(Conversion $clone $false)}
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();interfaceName=[ICloneable].FullName;interfaceMethods=@([ICloneable].GetMethods()|ForEach-Object ToString);profiles=$rows;qualification='SELECTED_ENCODING_CLONE_ONLY; FALLBACK_CUSTOMIZATION_INTERFACE_REFLECTION_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 11)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS pinned Encoding clone: six profiles including default singleton and derived state'
